<?php
// Dynamic XML sitemap (always reflects the current catalogue).
// /sitemap.xml is rewritten here by .htaccess; a static copy is also generated by scripts/build-seo-files.php.
require_once __DIR__ . '/sitemap_lib.php';

$xml = sitemap_xml(sitemap_entries());
header('Content-Type: application/xml; charset=utf-8');
header('Cache-Control: public, max-age=3600');
header('X-Robots-Tag: noindex');
echo $xml;
